/// GSOV 服务状态
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum GsvStatus {
    /// 未启动
    Stopped,
    /// 进程已拉起, 模型仍在加载
    Starting,
    /// API 已可服务
    Ready,
    /// 启动失败或进程异常退出
    Error,
}

/// 推送给前端的事件
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase", tag = "type")]
pub enum VoiceEvent {
    /// GSOV 进程输出的一行日志
    Log { line: String },
    /// 状态变化
    Status {
        status: GsvStatus,
        detail: Option<String>,
    },
}

/// GSOV 进程与状态
pub struct VoiceState {
    config: Mutex<Option<LaunchConfig>>,
    child: Mutex<Option<Child>>,
    status: Mutex<GsvStatus>,
    detail: Mutex<Option<String>>,
    logs: Mutex<Vec<String>>,
}

/// 日志缓冲区上限 (行)
const LOG_LIMIT: usize = 500;

impl Default for VoiceState {
    fn default() -> Self {
        Self {
            config: Mutex::new(None),
            child: Mutex::new(None),
            status: Mutex::new(GsvStatus::Stopped),
            detail: Mutex::new(None),
            logs: Mutex::new(Vec::new()),
        }
    }
}

impl VoiceState {
    async fn set_status(
        &self,
        status: GsvStatus,
        detail: Option<String>,
        channel: Option<&Channel<VoiceEvent>>,
    ) {
        *self.status.lock().await = status;
        *self.detail.lock().await = detail.clone();
        if let Some(channel) = channel {
            let _ = channel.send(VoiceEvent::Status { status, detail });
        }
    }

    async fn push_log(&self, line: String, channel: Option<&Channel<VoiceEvent>>) {
        {
            let mut logs = self.logs.lock().await;
            if logs.len() >= LOG_LIMIT {
                logs.remove(0);
            }
            logs.push(line.clone());
        }
        if let Some(channel) = channel {
            let _ = channel.send(VoiceEvent::Log { line });
        }
    }

    /// 关闭 GSOV 进程 (优先优雅退出, 超时后强杀)
    pub async fn shutdown(&self) {
        let mut guard = self.child.lock().await;
        let Some(mut child) = guard.take() else {
            return;
        };
        if let Some(config) = self.config.lock().await.clone() {
            let client = gsov::GsvClient::new(&config.host, config.port);
            let _ =
                tokio::time::timeout(std::time::Duration::from_secs(2), client.shutdown()).await;
        }
        // 给服务端一点时间自行退出 (它会落盘推理配置)
        let exited = tokio::time::timeout(std::time::Duration::from_secs(3), child.wait())
            .await
            .is_ok();
        if !exited {
            let _ = child.kill().await;
            let _ = child.wait().await;
        }
        *self.status.lock().await = GsvStatus::Stopped;
    }
}

