/// 启动 GSOV 服务
#[tauri::command]
pub async fn voice_launch(
    state: tauri::State<'_, Arc<VoiceState>>,
    config: LaunchConfig,
    on_event: Channel<VoiceEvent>,
) -> Result<(), String> {
    state.shutdown().await;

    let command = config.build_command();
    if !Path::new(&command.cwd).is_dir() {
        return Err(format!("工作目录不存在: {}", command.cwd.display()));
    }

    let mut process = Command::new(&command.program);
    process
        .args(&command.args)
        .current_dir(&command.cwd)
        // 统一 UTF-8 输出; 关闭 coloredlogs 的自动安装钩子, 保证日志可预测
        .env("PYTHONIOENCODING", "utf-8")
        .env("PYTHONUTF8", "1")
        .env("HF_HUB_OFFLINE", "1")
        .env("COLOREDLOGS_AUTO_INSTALL", "0")
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .kill_on_drop(true);

    let mut child = process
        .spawn()
        .map_err(|error| format!("无法启动 GSOV 进程 ({}): {error}", command.program))?;

    // 日志读取: 两个流共用一个切分器, 保证进度条不会被拆成两半
    let splitter = Arc::new(std::sync::Mutex::new(LineSplitter::new()));
    let state_arc: Arc<VoiceState> = state.inner().clone();

    if let Some(stdout) = child.stdout.take() {
        spawn_log_reader(
            stdout,
            splitter.clone(),
            state_arc.clone(),
            on_event.clone(),
        );
    }
    if let Some(stderr) = child.stderr.take() {
        spawn_log_reader(
            stderr,
            splitter.clone(),
            state_arc.clone(),
            on_event.clone(),
        );
    }

    *state.config.lock().await = Some(config.clone());
    *state.child.lock().await = Some(child);
    state
        .set_status(GsvStatus::Starting, None, Some(&on_event))
        .await;
    state
        .push_log(
            format!("$ {} {}", command.program, command.args.join(" ")),
            Some(&on_event),
        )
        .await;

    Ok(())
}

fn spawn_log_reader<R>(
    reader: R,
    splitter: Arc<std::sync::Mutex<LineSplitter>>,
    state: Arc<VoiceState>,
    channel: Channel<VoiceEvent>,
) where
    R: tokio::io::AsyncRead + Unpin + Send + 'static,
{
    tauri::async_runtime::spawn(async move {
        let mut lines = BufReader::new(reader).lines();
        while let Ok(Some(line)) = lines.next_line().await {
            let split = splitter
                .lock()
                .map(|mut s| s.push(&line))
                .unwrap_or_default();
            for entry in split {
                state.push_log(entry, Some(&channel)).await;
            }
        }
        // 进程结束时交出缓冲区残留 (无换行结尾的最后一行)
        let tail = splitter.lock().map(|mut s| s.flush()).unwrap_or_default();
        if let Some(line) = tail {
            state.push_log(line, Some(&channel)).await;
        }
    });
}

