/// 就绪探测: 命中后状态置为 `Ready`
#[tauri::command]
pub async fn voice_probe(
    state: tauri::State<'_, Arc<VoiceState>>,
    host: Option<String>,
    port: Option<u16>,
) -> Result<bool, String> {
    let config = state.config.lock().await.clone();
    let host = host
        .or_else(|| config.as_ref().map(|config| config.host.clone()))
        .unwrap_or_else(|| launcher::DEFAULT_HOST.to_string());
    let port = port
        .or_else(|| config.as_ref().map(|config| config.port))
        .unwrap_or(launcher::DEFAULT_PORT);

    // 进程已退出时直接判定失败, 避免前端无限等待
    {
        let mut guard = state.child.lock().await;
        if let Some(child) = guard.as_mut() {
            if let Ok(Some(status)) = child.try_wait() {
                let detail = format!("GSOV 进程已退出 ({status})");
                *guard = None;
                drop(guard);
                let state_arc: Arc<VoiceState> = state.inner().clone();
                state_arc
                    .set_status(GsvStatus::Error, Some(detail.clone()), None)
                    .await;
                return Err(detail);
            }
        }
    }

    let client = gsov::GsvClient::new(&host, port);
    match client.probe().await {
        Ok(()) => {
            let state_arc: Arc<VoiceState> = state.inner().clone();
            state_arc.set_status(GsvStatus::Ready, None, None).await;
            Ok(true)
        }
        Err(error) => {
            // 仅保留诊断信息, 状态仍为 Starting (由前端决定何时判超时)
            *state.detail.lock().await = Some(error.to_string());
            Ok(false)
        }
    }
}

