/// 一次配音生成的入参
#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SynthesizeRequest {
    /// 待合成文本 (来自场景对话)
    pub text: String,
    /// 文本语言码
    pub text_lang: String,
    /// 参考音频在服务端本机可见的绝对路径
    pub ref_audio_path: String,
    /// 参考文本 (v4 必需, 且须与音频逐字一致)
    pub prompt_text: String,
    /// 参考文本语言码
    pub prompt_lang: String,
    /// 采样步数: 测试 4 / 正式 32
    pub sample_steps: u32,
    pub temperature: f32,
    pub speed_factor: f32,
    pub top_k: u32,
    pub top_p: f32,
    pub repetition_penalty: f32,
    /// 文本切分方式 (默认 cut5)
    #[serde(default)]
    pub text_split_method: Option<String>,
    /// 随机种子; `-1` 表示由服务端随机
    #[serde(default)]
    pub seed: Option<i64>,
}

/// 推理结果: 已落盘的缓存条目
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct SynthesizeResult {
    pub entry: CacheEntry,
    /// 服务端返回的音频时长 (秒)
    pub duration: f64,
    pub sample_rate: u32,
}

/// 执行一次配音生成, 并把结果写入内容寻址的本地缓存。
///
/// 调用方 (**前端队列**) 必须保证串行: GSOV 后端为单进程单 worker 且持有全局
/// prompt 缓存, 并发请求会互相干扰。
#[tauri::command]
pub async fn voice_synthesize(
    app: tauri::AppHandle,
    state: tauri::State<'_, Arc<VoiceState>>,
    request: SynthesizeRequest,
) -> Result<SynthesizeResult, String> {
    if !gsov::SAMPLE_STEPS.contains(&request.sample_steps) {
        return Err(format!(
            "采样步数 {} 不受 v4 模型支持 (仅 {:?})",
            request.sample_steps,
            gsov::SAMPLE_STEPS
        ));
    }
    if request.prompt_text.trim().is_empty() {
        return Err("参考文本不可为空 (v4 模型必需)".into());
    }
    if !Path::new(&request.ref_audio_path).is_file() {
        return Err(format!("参考音频不存在: {}", request.ref_audio_path));
    }

    let config = state
        .config
        .lock()
        .await
        .clone()
        .ok_or_else(|| "GSOV 尚未配置启动参数".to_string())?;

    let mut tts = gsov::TtsRequest::new(
        request.text,
        request.text_lang,
        request.ref_audio_path,
        request.prompt_text,
        request.prompt_lang,
    );
    tts.sample_steps = request.sample_steps;
    tts.temperature = request.temperature;
    tts.speed_factor = request.speed_factor;
    tts.top_k = request.top_k;
    tts.top_p = request.top_p;
    tts.repetition_penalty = request.repetition_penalty;
    if let Some(method) = request.text_split_method {
        tts.text_split_method = method;
    }
    if let Some(seed) = request.seed {
        tts.seed = seed;
    }

    let client = gsov::GsvClient::new(&config.host, config.port);
    let bytes = client
        .synthesize(&tts)
        .await
        .map_err(|error| error.to_string())?;

    // 先在临时目录落盘再入库, 保证缓存只出现完整文件
    let root = cache_root(&app)?;
    std::fs::create_dir_all(&root).map_err(|error| error.to_string())?;
    let staging = root.join("staging.wav");
    std::fs::write(&staging, &bytes).map_err(|error| format!("写入配音缓存失败: {error}"))?;

    let probe = audio::probe(&staging)?;
    if probe.duration <= 0.0 {
        let _ = std::fs::remove_file(&staging);
        return Err("服务端返回了空音频".into());
    }

    let hash = audio::hash_file(&staging)?;
    let target = root.join(format!("{hash}.wav"));
    if target.is_file() {
        let _ = std::fs::remove_file(&staging);
    } else {
        std::fs::rename(&staging, &target).map_err(|error| format!("写入配音缓存失败: {error}"))?;
    }

    let size = std::fs::metadata(&target)
        .map_err(|error| error.to_string())?
        .len();
    Ok(SynthesizeResult {
        entry: CacheEntry {
            hash,
            path: target.display().to_string(),
            size,
            modified_at: library::now_millis(),
        },
        duration: probe.duration,
        sample_rate: probe.sample_rate,
    })
}

/// 显式切换 GSOV 权重。
///
/// 刻意设计为用户显式触发: 服务端切换权重会重载模型并落盘配置, 属于高代价操作。
/// 队列通过按角色分组让同角色任务连续执行, 从而避免频繁切换。
#[tauri::command]
pub async fn voice_set_model(
    state: tauri::State<'_, Arc<VoiceState>>,
    gpt_weights: Option<String>,
    sovits_weights: Option<String>,
) -> Result<(), String> {
    let config = state
        .config
        .lock()
        .await
        .clone()
        .ok_or_else(|| "GSOV 尚未配置启动参数".to_string())?;
    let client = gsov::GsvClient::new(&config.host, config.port);
    if let Some(path) = gpt_weights {
        client
            .set_gpt_weights(&path)
            .await
            .map_err(|error| format!("切换 GPT 权重失败: {error}"))?;
    }
    if let Some(path) = sovits_weights {
        client
            .set_sovits_weights(&path)
            .await
            .map_err(|error| format!("切换 SoVITS 权重失败: {error}"))?;
    }
    Ok(())
}

