/// 把音频读为 data URL (供前端试听; 参考音频体积很小, 无需额外 HTTP 服务)
#[tauri::command]
pub async fn voice_read_audio(path: String) -> Result<String, String> {
    let bytes = std::fs::read(&path).map_err(|error| format!("读取音频失败: {error}"))?;
    if bytes.len() > 32 * 1024 * 1024 {
        return Err("音频文件过大, 无法在编辑器内试听".into());
    }
    Ok(format!("data:audio/wav;base64,{}", base64_encode(&bytes)))
}

/// 标准 base64 编码 (避免为一次试听引入依赖)
fn base64_encode(bytes: &[u8]) -> String {
    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity(bytes.len().div_ceil(3) * 4);
    for chunk in bytes.chunks(3) {
        let byte0 = chunk[0] as u32;
        let byte1 = chunk.get(1).copied().unwrap_or(0) as u32;
        let byte2 = chunk.get(2).copied().unwrap_or(0) as u32;
        let triple = (byte0 << 16) | (byte1 << 8) | byte2;
        out.push(TABLE[(triple >> 18) as usize & 0x3F] as char);
        out.push(TABLE[(triple >> 12) as usize & 0x3F] as char);
        out.push(if chunk.len() > 1 {
            TABLE[(triple >> 6) as usize & 0x3F] as char
        } else {
            '='
        });
        out.push(if chunk.len() > 2 {
            TABLE[triple as usize & 0x3F] as char
        } else {
            '='
        });
    }
    out
}

// -------- 命令: 角色库 --------

/// 角色库根目录: `<appdata>/characters`
pub fn characters_root(app: &tauri::AppHandle) -> Result<PathBuf, String> {
    let dir = app
        .path()
        .app_data_dir()
        .map_err(|error| format!("无法定位应用数据目录: {error}"))?;
    Ok(dir.join("characters"))
}

/// 配音缓存根目录: `<appdata>/tts`
pub fn cache_root(app: &tauri::AppHandle) -> Result<PathBuf, String> {
    let dir = app
        .path()
        .app_data_dir()
        .map_err(|error| format!("无法定位应用数据目录: {error}"))?;
    Ok(dir.join("tts"))
}

fn library_of(app: &tauri::AppHandle) -> Result<library::Library, String> {
    Ok(library::Library::new(characters_root(app)?))
}

