/// 新建角色的入参
#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct NewCharacter {
    pub name: String,
    #[serde(default)]
    pub description: String,
    #[serde(default = "default_language")]
    pub language: String,
}

fn default_language() -> String {
    "auto".into()
}

/// 新建角色 (自动生成不与现有角色冲突的 id)
#[tauri::command]
pub async fn voice_create_character(
    app: tauri::AppHandle,
    input: NewCharacter,
) -> Result<library::Character, String> {
    let name = input.name.trim();
    if name.is_empty() {
        return Err("角色名不可为空".into());
    }
    let library = library_of(&app)?;
    let root = characters_root(&app)?;
    std::fs::create_dir_all(&root).map_err(|error| error.to_string())?;
    let id = library::unique_id(&root, name);
    let now = library::now_millis();
    let character = library::Character {
        id,
        name: name.to_string(),
        description: input.description,
        language: input.language,
        references: Vec::new(),
        model: None,
        starred: false,
        enabled: true,
        created_at: now,
        updated_at: now,
    };
    library.save(character).map_err(|error| error.to_string())
}

/// 添加参考音频的入参
#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ReferenceInput {
    /// 源音频路径 (任意用户可见位置, 会被拷贝进角色库)
    pub source: String,
    /// 参考文本 (v4 必需, 且须与音频逐字一致)
    pub text: String,
    /// 语言码
    pub language: String,
    /// 风格标签 (v0.5 仅 Ink 内部使用)
    #[serde(default)]
    pub tags: Vec<String>,
    /// 裁剪区间起点 (秒); 与 `end` 同时给出才生效
    #[serde(default)]
    pub start: Option<f64>,
    /// 裁剪区间终点 (秒)
    #[serde(default)]
    pub end: Option<f64>,
}

/// 添加参考音频: 规范化 (3~10 秒约束) 后纳入角色库
#[tauri::command]
pub async fn voice_add_reference(
    app: tauri::AppHandle,
    id: String,
    input: ReferenceInput,
) -> Result<library::Character, String> {
    let library = library_of(&app)?;
    let mut character = library.load(&id).map_err(|error| error.to_string())?;

    let dir = characters_root(&app)?.join(&id);
    std::fs::create_dir_all(&dir).map_err(|error| error.to_string())?;
    let staged = dir.join("staged.wav");

    let range = match (input.start, input.end) {
        (Some(start), Some(end)) => Some((start, end)),
        _ => None,
    };
    audio::normalize_reference(Path::new(&input.source), &staged, range)?;

    let reference = library
        .adopt_reference(&id, &staged, input.text, input.language, input.tags)
        .map_err(|error| error.to_string())?;
    let _ = std::fs::remove_file(&staged);

    character.references.push(reference);
    library.save(character).map_err(|error| error.to_string())
}

/// 移除参考音频 (仅当库内无其他条目引用同一文件时才删除文件)
#[tauri::command]
pub async fn voice_remove_reference(
    app: tauri::AppHandle,
    id: String,
    hash: String,
) -> Result<library::Character, String> {
    let library = library_of(&app)?;
    let mut character = library.load(&id).map_err(|error| error.to_string())?;
    let removed: Vec<_> = character
        .references
        .iter()
        .filter(|reference| reference.hash == hash)
        .map(|reference| reference.file.clone())
        .collect();
    character
        .references
        .retain(|reference| reference.hash != hash);

    for file in removed {
        let still_used = character
            .references
            .iter()
            .any(|reference| reference.file == file);
        library
            .drop_reference_file(&id, &file, still_used)
            .map_err(|error| error.to_string())?;
    }
    library.save(character).map_err(|error| error.to_string())
}

